import '../../domain/entities/business.dart';

class BusinessCategoryModel extends BusinessCategory { const BusinessCategoryModel({required super.id, required super.name, required super.slug}); factory BusinessCategoryModel.fromJson(Map<String, dynamic> json) => BusinessCategoryModel(id: json['id'] as String, name: json['name'] as String, slug: json['slug'] as String); }
class QueueSummaryModel extends QueueSummary { const QueueSummaryModel({required super.status, required super.peopleWaiting, required super.estimatedWaitingTimeMinutes, required super.averageServiceTimeMinutes, super.id, super.currentNumber}); factory QueueSummaryModel.fromJson(Map<String, dynamic> json) => QueueSummaryModel(id: json['id'] as String?, status: json['status'] as String, currentNumber: json['currentNumber'] as String?, peopleWaiting: (json['peopleWaiting'] as num).toInt(), estimatedWaitingTimeMinutes: (json['estimatedWaitingTimeMinutes'] as num).toInt(), averageServiceTimeMinutes: (json['averageServiceTimeMinutes'] as num).toInt()); }
class BusinessServiceItemModel extends BusinessServiceItem { const BusinessServiceItemModel({required super.id, required super.name, super.estimatedDurationMinutes, super.price}); factory BusinessServiceItemModel.fromJson(Map<String, dynamic> json) => BusinessServiceItemModel(id: json['id'] as String, name: json['name'] as String, estimatedDurationMinutes: (json['estimatedDurationMinutes'] as num?)?.toInt(), price: json['price'] as num?); }
class BusinessModel extends Business { const BusinessModel({required super.id, required super.name, required super.address, required super.category, required super.queue, super.description, super.imageUrl, super.rating, super.distanceKm, super.openingHours, super.services}); factory BusinessModel.fromJson(Map<String, dynamic> json) => BusinessModel(id: json['id'] as String, name: json['name'] as String, description: json['description'] as String?, imageUrl: json['imageUrl'] as String?, rating: json['rating'] as num?, address: json['address'] as String, distanceKm: json['distanceKm'] as num?, category: BusinessCategoryModel.fromJson(json['category'] as Map<String, dynamic>), queue: QueueSummaryModel.fromJson(json['queue'] as Map<String, dynamic>), openingHours: json['openingHours'], services: ((json['services'] as List?) ?? const []).map((item) => BusinessServiceItemModel.fromJson(item as Map<String, dynamic>)).toList()); }